import{_ as t,a as o,b as a,c as n,d as r,e as i,f as s,g as c,h as p}from"./chunks/hydration-overlay-ecom.BWr90E80.js";import{_ as l,o as h,c as d,aj as u}from"./chunks/framework.C6uXqnaX.js";const x=JSON.parse('{"title":"Inspect the component tree","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"tools/devtools/component.md","filePath":"tools/devtools/component.md"}'),m={name:"tools/devtools/component.md"};function g(f,e,v,b,y,_){return h(),d("div",null,e[0]||(e[0]=[u('<h1 id="inspect-the-component-tree" tabindex="-1">Inspect the component tree <a class="header-anchor" href="#inspect-the-component-tree" aria-label="Permalink to &quot;Inspect the component tree&quot;">​</a></h1><h2 id="debug-your-application" tabindex="-1">Debug your application <a class="header-anchor" href="#debug-your-application" aria-label="Permalink to &quot;Debug your application&quot;">​</a></h2><p>The <strong>Components</strong> tab lets you explore the structure of your application. You can visualize the component and directive instances in the DOM and inspect or modify their state.</p><h3 id="explore-the-application-structure" tabindex="-1">Explore the application structure <a class="header-anchor" href="#explore-the-application-structure" aria-label="Permalink to &quot;Explore the application structure&quot;">​</a></h3><p>The component tree displays a hierarchical relationship of the <em>components and directives</em> within your application.</p><img src="'+t+'" alt="A screenshot of the &#39;Components&#39; tab showing a tree of Angular components and directives starting the root of the application."><p>Click the individual components or directives in the component explorer to select them and preview their properties. Angular DevTools displays properties and metadata on the right side of the component tree.</p><p>To look up a component or directive by name use the search box above the component tree.</p><img src="'+o+'" alt="A screenshot of the &#39;Components&#39; tab. The filter bar immediately underneath the tab is searching for &#39;todo&#39; and all components with &#39;todo&#39; in the name are highlighted in the tree. `app-todos` is currently selected and a sidebar to the right displays information about the component&#39;s properties. This includes a section of `@Output` fields and another section for other properties."><h3 id="navigate-to-the-host-node" tabindex="-1">Navigate to the host node <a class="header-anchor" href="#navigate-to-the-host-node" aria-label="Permalink to &quot;Navigate to the host node&quot;">​</a></h3><p>To go to the host element of a particular component or directive, double-click it in the component explorer. Angular DevTools will open the Elements tab in Chrome or the Inspector tab in Firefox, and select the associated DOM node.</p><h3 id="navigate-to-source" tabindex="-1">Navigate to source <a class="header-anchor" href="#navigate-to-source" aria-label="Permalink to &quot;Navigate to source&quot;">​</a></h3><p>For components, Angular DevTools lets you navigate to the component definition in the Sources tab (Chrome) and Debugger tab (Firefox). After you select a particular component, click the icon at the top-right of the properties view:</p><img src="'+a+'" alt="A screenshot of the &#39;Components&#39; tab. The properties view on the right is visible for a component and the mouse rests in the upper right corner of that view on top of a `&lt;&gt;` icon. An adjacent tooltip reads &#39;Open component source&#39;."><h3 id="update-property-value" tabindex="-1">Update property value <a class="header-anchor" href="#update-property-value" aria-label="Permalink to &quot;Update property value&quot;">​</a></h3><p>Like browsers&#39; DevTools, the properties view lets you edit the value of an input, output, or other properties. Right-click on the property value and if edit functionality is available for this value type, a text input will appear. Type the new value and press <code>Enter</code> to apply this value to the property.</p><img src="'+n+'" alt="A screenshot of the &#39;Components&#39; tab with the properties view open for a component. An `@Input` named `todo` contains a `label` property which is currently selected and has been manually updated to the value &#39;Buy milk&#39;."><h3 id="access-selected-component-or-directive-in-console" tabindex="-1">Access selected component or directive in console <a class="header-anchor" href="#access-selected-component-or-directive-in-console" aria-label="Permalink to &quot;Access selected component or directive in console&quot;">​</a></h3><p>As a shortcut in the console, Angular DevTools provides access to instances of recently selected components or directives. Type <code>$ng0</code> to get a reference to the instance of the currently selected component or directive, and type <code>$ng1</code> for the previously selected instance, <code>$ng2</code> for the instance selected before that, and so on.</p><img src="'+r+'" alt="A screenshot of the &#39;Components&#39; tab with the browser console underneath. In the console, the user has typed three commands, `$ng0`, `$ng1`, and `$ng2` to view the three most recently selected elements. After each statement, the console prints a different component reference."><h3 id="select-a-directive-or-component" tabindex="-1">Select a directive or component <a class="header-anchor" href="#select-a-directive-or-component" aria-label="Permalink to &quot;Select a directive or component&quot;">​</a></h3><p>Similar to browsers&#39; DevTools, you can inspect the page to select a particular component or directive. Click the <strong><em>Inspect element</em></strong> icon in the top left corner within Angular DevTools and hover over a DOM element on the page. The extension recognizes the associated directives and/or components and lets you select the corresponding element in the Component tree.</p><img src="'+i+'" alt="A screenshot of the &#39;Components&#39; tab with an Angular todo application visible. In the very top-left corner of Angular DevTools, an icon of a screen with a mouse icon inside it is selected. The mouse rests on a todo element in the Angular application UI. The element is highlighted with a `&lt;TodoComponent&gt;` label displayed in an adjacent tooltip."><h3 id="inspect-deferrable-views" tabindex="-1">Inspect Deferrable views <a class="header-anchor" href="#inspect-deferrable-views" aria-label="Permalink to &quot;Inspect Deferrable views&quot;">​</a></h3><p>Alongside the directives, the directive tree also includes <a href="/guide/templates/defer"><code>@defer</code> blocks</a>.</p><img src="'+s+'"><p>Clicking a defer block shows more details in the properties sidebar: the different optional blocks (for example <code>@loading</code>, <code>@placeholder</code>, and <code>@error</code>), the configured triggers (defer triggers, prefetch triggers, and hydrate triggers), and timing options such as the <code>minimum</code> and <code>after</code> values.</p><h3 id="hydration" tabindex="-1">Hydration <a class="header-anchor" href="#hydration" aria-label="Permalink to &quot;Hydration&quot;">​</a></h3><p>When <a href="/guide/hydration">hydration</a> is enabled on your SSR/SSG application, the directive tree shows the hydration status of each component.</p><p>In case of errors, an error message is displayed on the affected component.</p><img src="'+c+'"><p>The hydration status can also be visualized on the application itself by enabling the overlay.</p><img src="'+p+'"><p>Here is an illustration of the hydration overlays on a Angular e-shop example app.</p><h3 id="debug-the-signal-graph" tabindex="-1">Debug the signal graph <a class="header-anchor" href="#debug-the-signal-graph" aria-label="Permalink to &quot;Debug the signal graph&quot;">​</a></h3><p>To visualize how the signals, computeds, and effects of a component depend on each other, see <a href="/tools/devtools/signals">Debug the signal graph</a>.</p>',36)]))}const A=l(m,[["render",g]]);export{x as __pageData,A as default};
